) as v(tracker_id, date, description, payee, amount, currency, kind, category, project, funding, account_id, payer, receipt_link, approval_basis, decided_by, notes)
on conflict (tracker_id) do update set
  date = excluded.date, description = excluded.description, payee = excluded.payee, amount = excluded.amount, currency = excluded.currency,
  kind = excluded.kind, category = excluded.category, project = excluded.project, funding = excluded.funding, account_id = excluded.account_id,
  payer = excluded.payer, receipt_link = excluded.receipt_link, approval_basis = excluded.approval_basis, decided_by = excluded.decided_by,
  notes = excluded.notes, status = 'Approved', imported = true;

-- Everything imported counts as approved; approvals apply to new payments only.
update public.payments set status = 'Approved',
  approval_basis = coalesce(approval_basis, 'Treated as approved on import (instruction of 20 Nov 2026)')
  where imported and status <> 'Approved';

-- Check: expect 135 imported, all approved.
select to_char(date,'YYYY-MM') as month, funding, count(*), sum(case when currency='TZS' then amount end) as tzs, sum(case when currency='USD' then amount end) as usd
from public.payments where imported group by 1,2 order by 1,2;
